#include <cmath>
#include <iomanip>
#include <iostream>
#include <vector>
using V=std::vector<double>;
static double dot(const V&a,const V&b){double s=0;for(size_t i=0;i<a.size();++i)s+=a[i]*b[i];return s;}
int main(){
  int N,D;if(!(std::cin>>N>>D)||N<=0||D!=2)return 2;
  std::vector<V>x(N,V(D));std::vector<int>y(N);
  for(int i=0;i<N;++i){std::cin>>y[i];for(int d=0;d<D;++d)std::cin>>x[i][d];}
  double lr,limit;int max_epochs;std::cin>>lr>>limit>>max_epochs;
  std::vector<double>a(N,0.0);double beta=1.0;bool converged=false;
  for(int epoch=0;epoch<max_epochs;++epoch){
    bool judge=false;
    for(int i=0;i<N;++i){
      double item1=0,item2=0;
      for(int k=0;k<N;++k){item1+=a[k]*y[i]*y[k]*dot(x[i],x[k]);item2+=a[k]*y[i]*y[k];}
      double delta=1.0-item1-beta*item2;a[i]+=lr*delta;
      if(a[i]<0)a[i]=0;else if(std::abs(delta)>limit)judge=true;
    }
    double item3=0;for(int i=0;i<N;++i)item3+=a[i]*y[i];beta+=item3*item3/2.0;
    if(!judge){converged=true;break;}
  }
  if(!converged)return 3;
  V w(D,0.0);double b=0;int ns=0;
  for(int i=0;i<N;++i)if(a[i]>1e-7){++ns;for(int d=0;d<D;++d)w[d]+=a[i]*y[i]*x[i][d];}
  if(ns==0)return 4;
  for(int i=0;i<N;++i)if(a[i]>1e-7)b+=y[i]-dot(w,x[i]);b/=ns;
  std::cout<<std::setprecision(17)<<"SVM "<<w[0]<<" "<<w[1]<<" "<<b;
  for(int i=0;i<N;++i)std::cout<<" "<<(dot(w,x[i])+b>=0?1:-1);
  std::cout<<"\n";
}

