#include <cmath>
#include <iomanip>
#include <iostream>
#include <vector>
int main(){
  int N,K,iters;if(!(std::cin>>N>>K>>iters)||N<=0||K!=2)return 2;
  const double pi=3.141592653589793;
  std::vector<double>x(N),w(K),m(K),v(K);for(double&z:x)std::cin>>z;for(double&z:w)std::cin>>z;for(double&z:m)std::cin>>z;for(double&z:v)std::cin>>z;
  std::vector<std::vector<double>>r(N,std::vector<double>(K));
  for(int it=0;it<iters;++it){
    for(int i=0;i<N;++i){double s=0;for(int k=0;k<K;++k){double d=x[i]-m[k];r[i][k]=w[k]*std::exp(-0.5*d*d/v[k])/std::sqrt(2*pi*v[k]);s+=r[i][k];}for(int k=0;k<K;++k)r[i][k]/=s;}
    std::vector<double>nk(K,0),nm(K,0),nv(K,0);
    for(int k=0;k<K;++k){for(int i=0;i<N;++i)nk[k]+=r[i][k];w[k]=nk[k]/N;for(int i=0;i<N;++i)nm[k]+=r[i][k]*x[i];m[k]=nm[k]/nk[k];for(int i=0;i<N;++i){double d=x[i]-m[k];nv[k]+=r[i][k]*d*d;}v[k]=nv[k]/nk[k];}
  }
  double ll=0;for(double z:x){double s=0;for(int k=0;k<K;++k){double d=z-m[k];s+=w[k]*std::exp(-0.5*d*d/v[k])/std::sqrt(2*pi*v[k]);}ll+=std::log(s);}
  std::cout<<std::setprecision(17)<<"GMM "<<w[0]<<" "<<w[1]<<" "<<m[0]<<" "<<m[1]<<" "<<v[0]<<" "<<v[1]<<" "<<ll<<"\n";
}

