#include <iomanip>
#include <iostream>
#include <memory>
#include <unordered_set>
#include <vector>
struct V;using P=std::shared_ptr<V>;struct E{P p;double local;};struct V{double data,grad=0;std::vector<E>e;explicit V(double d):data(d){}};
static P val(double x){return std::make_shared<V>(x);}static P add(const P&a,const P&b){auto o=val(a->data+b->data);o->e={{a,1},{b,1}};return o;}static P mul(const P&a,const P&b){auto o=val(a->data*b->data);o->e={{a,b->data},{b,a->data}};return o;}
static void topo(const P&v,std::unordered_set<V*>&s,std::vector<P>&o){if(!s.insert(v.get()).second)return;for(auto&e:v->e)topo(e.p,s,o);o.push_back(v);}static void backward(const P&y){std::unordered_set<V*>s;std::vector<P>o;topo(y,s,o);for(auto&v:o)v->grad=0;y->grad=1;for(auto it=o.rbegin();it!=o.rend();++it)for(auto&e:(*it)->e)e.p->grad+=(*it)->grad*e.local;}
int main(){double a,b,c;if(!(std::cin>>a>>b>>c))return 2;auto x1=val(a),x2=val(b),x3=val(c);auto y=add(mul(mul(mul(mul(x1,x1),x1),x2),x2),mul(x1,x3));backward(y);std::cout<<std::setprecision(17)<<"LIGHTGRAD "<<y->data<<" "<<x1->grad<<" "<<x2->grad<<" "<<x3->grad<<"\n";}
